import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

import java.time.LocalDateTime;
import java.util.UUID;

// 1. 도메인 모델 및 멱등성 키 저장소
@Document(collection = "orders")
class Order {
    @Id
    private String id;
    private String orderId;
    private String customerId;
    private double amount;
    private LocalDateTime createdAt;

    public Order(String orderId, String customerId, double amount) {
        this.orderId = orderId;
        this.customerId = customerId;
        this.amount = amount;
        this.createdAt = LocalDateTime.now();
    }

    // Getters
    public String getId() { return id; }
    public String getOrderId() { return orderId; }
    public String getCustomerId() { return customerId; }
    public double getAmount() { return amount; }
    public LocalDateTime getCreatedAt() { return createdAt; }
}

// 2. 리포지토리 (멱등성 키 중복 체크 및 주문 저장)
interface OrderRepository {
    // 멱등성 키로 기존 주문이 있는지 확인 (트랜잭션 내에서 원자적으로 동작해야 함)
    Order findByOrderId(String orderId);

    // 주문 저장
    Order save(Order order);
}

// 3. 서비스 레이어 (비즈니스 로직 및 트랜잭션 경계)
class OrderService {
    private final OrderRepository orderRepository;

    public OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    /**
     * 주문 생성 서비스
     * @param idempotencyKey 클라이언트에서 전달한 고유 멱등성 키
     * @param customerId 고객 ID
     * @param amount 주문 금액
     * @return 생성된 주문 정보
     * @throws ResponseStatusException 중복 요청 또는 실패 시
     */
    @org.springframework.transaction.annotation.Transactional
    public Order createOrder(String idempotencyKey, String customerId, double amount) {
        // 1. 멱등성 키로 기존 주문 확인
        Order existingOrder = orderRepository.findByOrderId(idempotencyKey);

        if (existingOrder != null) {
            // 이미 처리된 주문이 있으면 기존 결과 반환 (멱등성 보장)
            return existingOrder;
        }

        // 2. 주문 생성
        Order newOrder = new Order(idempotencyKey, customerId, amount);

        try {
            // 3. 주문 저장 (DB 트랜잭션 내에서 저장)
            return orderRepository.save(newOrder);
        } catch (Exception e) {
            // 저장 실패 시 예외 던지기 (클라이언트는 실패 응답 처리)
            throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR, "주문 생성 중 오류 발생", e);
        }
    }
}

// 4. 컨트롤러 (HTTP 요청 처리)
@RestController
@RequestMapping("/api/orders")
class OrderController {
    private final OrderService orderService;

    public OrderController(OrderService orderService) {
        this.orderService = orderService;
    }

    @PostMapping
    public ResponseEntity<Order> createOrder(
            @RequestHeader("X-Idempotency-Key") String idempotencyKey,
            @RequestParam String customerId,
            @RequestParam double amount) {

        try {
            Order order = orderService.createOrder(idempotencyKey, customerId, amount);
            return ResponseEntity.status(HttpStatus.CREATED).body(order);
        } catch (ResponseStatusException e) {
            // 서비스 레이어에서 던진 예외 처리
            return ResponseEntity.status(e.getStatusCode()).body(null);
        } catch (Exception e) {
            // 예상치 못한 예외 처리
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(null);
        }
    }
}
