import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;
import java.util.concurrent.TimeUnit;

@Service
public class OrderService {

    private final StringRedisTemplate redisTemplate;
    private final OrderRepository orderRepository;

    public OrderService(StringRedisTemplate redisTemplate, OrderRepository orderRepository) {
        this.redisTemplate = redisTemplate;
        this.orderRepository = orderRepository;
    }

    /**
     * 멱등성 키를 사용하여 동시 요청 처리 및 중복 주문 방지
     * @param idempotencyKey 클라이언트가 생성한 고유 요청 ID
     * @param orderRequest 주문 정보
     * @return 생성된 주문 결과
     */
    @Transactional
    public OrderResponse createOrder(String idempotencyKey, OrderRequest orderRequest) {
        // 1. Redis 분산 락 또는 SETNX를 통한 동시 요청 제어
        // key: idempotency_key:{idempotencyKey}, value: "LOCK", expire: 5초
        Boolean isLocked = redisTemplate.opsForValue()
                .setIfAbsent("idempotency_key:" + idempotencyKey, "LOCK", 5, TimeUnit.SECONDS);

        if (Boolean.FALSE.equals(isLocked)) {
            // 이미 처리 중인 요청이거나 중복 요청
            throw new DuplicateRequestException("요청이 이미 처리 중이거나 중복 요청입니다.");
        }

        try {
            // 2. DB에서 이미 존재하는지 확인 (이중 체크 패턴 보완)
            Order existingOrder = orderRepository.findByIdempotencyKey(idempotencyKey);
            if (existingOrder != null) {
                return new OrderResponse(existingOrder.getId(), "SUCCESS", existingOrder.getStatus());
            }

            // 3. 주문 생성 로직
            Order newOrder = Order.builder()
                    .idempotencyKey(idempotencyKey)
                    .productId(orderRequest.getProductId())
                    .quantity(orderRequest.getQuantity())
                    .status(OrderStatus.PENDING)
                    .build();

            orderRepository.save(newOrder);

            // 4. 성공 시 Redis 키 삭제 (선택적: 상태 저장 시 유지 가능)
            redisTemplate.delete("idempotency_key:" + idempotencyKey);

            return new OrderResponse(newOrder.getId(), "SUCCESS", newOrder.getStatus());

        } catch (Exception e) {
            // 트랜잭션 롤백 시 Redis 락도 해제해야 함 (자동 해제됨)
            // 실패 응답 처리
            throw new OrderCreationFailedException("주문 생성에 실패했습니다.", e);
        }
    }
}
